const cases = [
  [-170n, -170n, 17n, -170n, -680n, 8n],
  [-580n, 70n, 1n, -930n, -101n, 4n],
  [28965600n, -2619769n, 182325n, 0n, -7293000n, 85800n],
  [-9860n, 1190n, 17n, -15810n, -1734n, 70n],
];
ceiling = Infinity;
const rows = cases.map((coefficients) => {
  const [a, b, c, d, e, f] = coefficients;
  const values = P.map(([t, B, D]) => a*t*t + b*B*B + c*D*D + d*t*B + e*t*D + f*B*D);
  if (values.some((value) => value === 0n)) throw Error('expected strict endpoint signs');
  let positive = 0n;
  let negative = 0n;
  for (const [u, , bit] of G) {
    if (values[u] > 0n) positive |= bit;
    else negative |= bit;
  }
  const start = checks;
  const allowed = [can(positive, 5), can(negative, 5)];
  if (allowed.every(Boolean) || count(positive) > 31 || count(negative) > 31) throw Error('unexpected capacity outcome');
  return {labels: [count(positive), count(negative)], allowed, checks: checks - start};
});
return rows;
